package net.civeira.phylax.feature.observe.observedsource.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class ObservedSourceFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_source_filter_builder() {
    ObservedSourceFilter filter = ObservedSourceFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getCode().isPresent(),
        "Code must be empty if filter is build without it");
    filter.setCode("one");
    Assertions.assertEquals("one", filter.getCode().get(), "Code must be the same as the assigned");
    Assertions.assertFalse(filter.getIngestKey().isPresent(),
        "IngestKey must be empty if filter is build without it");
    filter.setIngestKey("one");
    Assertions.assertEquals("one", filter.getIngestKey().get(),
        "IngestKey must be the same as the assigned");
    Assertions.assertFalse(filter.getOriginRef().isPresent(),
        "OriginRef must be empty if filter is build without it");
    filter.setOriginRef("one");
    Assertions.assertEquals("one", filter.getOriginRef().get(),
        "OriginRef must be the same as the assigned");
    Assertions.assertFalse(filter.getOriginType().isPresent(),
        "OriginType must be empty if filter is build without it");
    filter.setOriginType("one");
    Assertions.assertEquals("one", filter.getOriginType().get(),
        "OriginType must be the same as the assigned");
    Assertions.assertFalse(filter.getKind().isPresent(),
        "Kind must be empty if filter is build without it");
    filter.setKind(null);
    Assertions.assertFalse(filter.getKind().isPresent(), "Kind must be the same as the assigned");
  }
}
